<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';
import {api,can,type DataJob} from './api';
const props=defineProps<{kind?:string;title?:string}>();
const jobs=ref<DataJob[]>([]),error=ref(''),busy=ref(false);let timer:ReturnType<typeof setInterval>|undefined;
const stateNames:Record<string,string>={Queued:'等待执行',Running:'执行中',Completed:'已完成',Cancelled:'已取消',Failed:'失败',Interrupted:'服务退出前未完成'};
async function load(){if(busy.value)return;busy.value=true;try{jobs.value=await api('/api/data-jobs');error.value=''}catch(e){error.value=String(e)}finally{busy.value=false}}
async function cancel(id:string){try{await api('/api/data-jobs/'+id+'/cancel','POST',{});await load()}catch(e){error.value=String(e)}}
onMounted(()=>{void load();timer=setInterval(()=>void load(),2000)});onUnmounted(()=>{if(timer)clearInterval(timer)});defineExpose({load});
</script>
<template><section class="panel"><div class="toolbar"><h2>{{props.title||'后台数据任务'}}</h2><button class="button" :disabled="busy" @click="load">刷新</button></div><p v-if="error" role="alert" class="notice error-message">{{error}}</p><div class="table-wrap"><table><thead><tr><th>申请时间</th><th>类型</th><th>状态</th><th>处理进度</th><th>申请人</th><th>说明</th><th>操作</th></tr></thead><tbody><tr v-for="j in jobs.filter(j=>!props.kind||j.kind===props.kind)" :key="j.id"><td>{{new Date(j.createdAtUtc).toLocaleString('zh-CN',{hour12:false})}}</td><td>{{j.kind==='HistoryExport'?'历史Excel导出':j.kind==='DatabaseBackup'?'业务数据库备份':j.kind==='AverageTemperatureDispatch'?'定时平均测温申请':'数据快照'}}</td><td>{{j.kind==='AverageTemperatureDispatch'&&j.state==='Completed'?'申请已处理':stateNames[j.state]}}</td><td>{{j.rows.toLocaleString()}}{{j.kind==='DatabaseBackup'?' 页':j.kind==='AverageTemperatureDispatch'?' 罐':''}}</td><td>{{j.actorName}}</td><td>{{j.error||j.fileName||(j.snapshotId?'快照已保存':'—')}}</td><td><a v-if="j.state==='Completed'&&j.fileName&&(j.kind==='DatabaseBackup'?can('BackupManage'):can('DataExport'))" class="text-button" :href="'/api/data-jobs/'+j.id+'/download'">下载文件</a><button v-if="j.kind!=='AverageTemperatureDispatch'&&(j.state==='Queued'||j.state==='Running')" class="text-button" @click="cancel(j.id)">取消任务</button></td></tr><tr v-if="!jobs.some(j=>!props.kind||j.kind===props.kind)"><td colspan="7" class="empty">暂无数据任务</td></tr></tbody></table></div><div class="table-foot">历史在后台分片写入Excel；业务备份分步复制、检查完整性并附SHA256校验值，完成后下载。失败、取消或服务退出未完成的文件不发布；重新启动不会重放未完成的任务。</div></section></template>
